import numpy as np
from scipy import ndimage
z=np.load('source_pixels.npz')['rgb'].astype(np.float32)
# mask based on magenta difference b-g within moving zone
for i in [0,12,24,30,36,42,48,60,72,90]:
 f=z[i]; r,g,b=[f[...,k] for k in range(3)]
 for name,m in [('mag',(b-g>15)&(b-r>-10)&(r>150)),('pink',(r-g>18)&(b-g>15)&(r>170))]:
  mm=np.zeros_like(m); mm[50:105,55:180]=m[50:105,55:180]
  lab,n=ndimage.label(mm); comps=[]
  for j in range(1,n+1):
   ys,xs=np.where(lab==j); a=len(xs)
   if a>=5: comps.append((a,int(xs.min()),int(ys.min()),int(xs.max()),int(ys.max())))
  if name=='pink': print(i,m.sum(),sorted(comps,reverse=True)[:6])
PY"

