import numpy as np
z=np.load('source_pixels.npz')['rgb'].astype(np.float32)
# Print per-row x ranges for strong red R and magenta P from classification in each frame around final pose; helpful to determine head mask
for i in [0,24,48,60,95]:
 f=z[i]; print('\\nFRAME',i)
 for y in range(68,88):
  R=[];P=[]
  for x in range(90,135):
   r,g,b=f[y,x]
   if r-g>35 and abs(b-g)<30: R.append(x)
   if r-g>25 and b-g>10:P.append(x)
  def runs(a):
   a=np.array(a); return [(int(a[k]),int(a[j])) for k,j in []] # dummy
  if R or P:
   def fmt(a):
    if not a:return '-'
    a=np.array(a); starts=a[np.r_[True,np.diff(a)>1]]; ends=a[np.r_[np.diff(a)>1,True]]; return ','.join(f'{s}-{e}' for s,e in zip(starts,ends))
   print(y,'R',fmt(R),'P',fmt(P))
PY"

